const e="deped-cabuyao-festival-of-talents",d=2017,n="Past edition (19 Sep 2017), image-only PDF read page by page; there is no rulebook beyond this memorandum. Not printed: registration form, deadline, entry fee, prizes, points, grades, ranks, contact numbers or emails. The planning committee and contest-proper committee names are printed but are not copied.",t={Title:"Rules & Criteria",Subtitle:"Division Festival of Talents (PopQuiz and On-the-Spot Skills Exhibition). Rules as printed for the 2017 edition; check the current memorandum.",NoticeTitle:"Please Read Before Registering",Notice:"The 2017 edition was held on {{EventDate}}, {{EventTime}}, at {{Venue}}. Contestants register 30 minutes before the contest proper. No materials or electronic devices are allowed.",Notes:["These rules are from the 2017 edition. Dates, venue and officials are the past edition's values."],Sections:[{Key:"general",Title:"General Rules",Items:["The Festival of Talents is an annual activity started in 2012. It lets students show their knowledge and skills in different learning areas.","It also lets students show their level of competence in population and development.","The key concepts are family life and responsible parenthood, gender and development, population and reproductive health, and environment, resources and sustainable development.","Aims: to showcase students' exemplary talents as evidence of their learning, and to strengthen and upgrade students' level of competence and confidence in facing life's challenges.","The 2017 programme was the Division PopQuiz and On-the-Spot Skills Exhibition, run by the Curriculum Implementation Division.","The mechanics follow Regional Memorandum 368 s. 2016. Questions for the local and national levels are based on the population education core messages above.","Review materials for the PopQuiz are provided by PopCom.","The people taking part are the Chief of the Curriculum Implementation Division, the Division AP Coordinator, public and private secondary school heads, contestants with their teacher-coaches, and the Technical Working Group."]},{Key:"eligibility",Title:"Who May Enter",Items:["Contestants are students of public and private junior high schools.","PopQuiz, Essay Writing, and Jingle Writing and Singing are open to Grade 10 students.","Poster Making is open to Grade 7 to 10 students.","Each school sends 1 contestant per category.","Contestants must be accompanied by teacher-coaches of the school they represent. Preferably there is one teacher-coach per category."]},{Key:"registration",Title:"How to Register",Items:["Contestants are expected to be at the venue 30 minutes before the contest proper for registration.","No registration form, deadline or fee is printed in the memorandum."]},{Key:"conduct",Title:"Conduct and Disqualification",Items:["Contestants wear the proper school uniform with school ID during the contest proper.","Contestants may not take hold of any materials or electronic communication devices during the competition.","A contestant found with a device during the contest proper is automatically disqualified."]},{Key:"judging",Title:"Judging",Items:["Judging criteria are set per contest, as shown on each competition. They total 100 for Essay Writing, Poster Making and Jingle Writing and Singing. PopQuiz is decided by cumulative score."]},{Key:"payments",Title:"Costs",Items:["Transportation and other incidental expenses are charged to local funds, under the usual accounting and auditing rules."]},{Key:"dates",Title:"Date and Time",Items:["The 2017 edition was held on {{EventDate}}, {{EventTime}}."]},{Key:"venue",Title:"Venue",Items:["The 2017 edition was held at {{Venue}}."]},{Key:"other",Title:"Not carried in this template",Items:["The opening and closing programme and the planning committees are printed in the memorandum but are not competitions."]}],Documents:[{Title:"Division Memorandum No. 79 s. 2017 (Festival of Talents, 2017 edition)",Url:"https://depedcabuyao.ph/wp-content/uploads/2017/09/Festival-of-Talents-Popquiz-and-On-the-Spot-Skills-Exhibition.pdf"}]},i=[],o=[{AgeGroup:"Grade 10",Source:"Memorandum No. 79 s. 2017, Guidelines D.1",Sections:{About:null,TimeAndFormat:null,Rules:["Open to Grade 10 students: PopQuiz, Essay Writing, and Jingle Writing and Singing. Grade 10 students may also enter Poster Making."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Open to Grade 10 students: PopQuiz, Essay Writing, and Jingle Writing and Singing. Grade 10 students may also enter Poster Making.`},{AgeGroup:"Grade 7-10",Source:"Memorandum No. 79 s. 2017, item 3 and Guidelines D.1",Sections:{About:null,TimeAndFormat:null,Rules:["Poster Making is open to Grade 7 to 10 students."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Poster Making is open to Grade 7 to 10 students.`}],a=[{Title:"PopQuiz",Source:"Memorandum No. 79 s. 2017, Implementing Guidelines, PopQuiz",Sections:{About:["A written quiz on the population education key concepts."],TimeAndFormat:["20 questions: 6 easy, 7 average and 7 difficult.","10 seconds to answer each question. Questions that need computation get a maximum of 30 seconds.","The quizmaster reads each question twice. The countdown starts after the second reading."],Rules:["Contestants get pens and numbered, colour-coded writing sheets. The proctor collects the writing sheet after each round.","English or Filipino is the official language of the quiz.","To change an answer, cross it out with one horizontal line and write the new answer clearly above it. An answer may be changed within the time for that question.","Only the official coach may raise a protest or inquiry, at the earliest appropriate time during the quiz.","The protest is made orally to the chair of the board of judges, who recognises it. The chair announces the decision after talking with the board of judges."],Allowed:null,NotAllowed:null,Judging:["A winner is proclaimed by cumulative score.","All ties are broken by a tiebreaker question from the difficult category."],Points:["Easy question: 1 point. Average question: 2 points. Difficult question: 3 points. The highest possible score is 41."],Notes:null},Markdown:`## About this competition
- A written quiz on the population education key concepts.

## Time and format
- 20 questions: 6 easy, 7 average and 7 difficult.
- 10 seconds to answer each question. Questions that need computation get a maximum of 30 seconds.
- The quizmaster reads each question twice. The countdown starts after the second reading.

## Rules
- Contestants get pens and numbered, colour-coded writing sheets. The proctor collects the writing sheet after each round.
- English or Filipino is the official language of the quiz.
- To change an answer, cross it out with one horizontal line and write the new answer clearly above it. An answer may be changed within the time for that question.
- Only the official coach may raise a protest or inquiry, at the earliest appropriate time during the quiz.
- The protest is made orally to the chair of the board of judges, who recognises it. The chair announces the decision after talking with the board of judges.

## Judging
- A winner is proclaimed by cumulative score.
- All ties are broken by a tiebreaker question from the difficult category.

## Points
- Easy question: 1 point. Average question: 2 points. Difficult question: 3 points. The highest possible score is 41.`},{Title:"Essay Writing",Source:"Memorandum No. 79 s. 2017, Implementing Guidelines, On-the-Spot Skills Exhibition",Sections:{About:null,TimeAndFormat:["At least 800 and not more than 1000 words in English.","Written legibly in double space on the writing pad provided.","The theme is announced on the day."],Rules:["The essay must be original and not published before.","Contestants bring their own materials."],Allowed:null,NotAllowed:null,Judging:["Presentation and Style 40%.","Form, Content and Insight 60%: Accuracy 20%, Fairness (balanced, sound) 20%, Methodology 20%."],Points:null,Notes:null},Markdown:`## Time and format
- At least 800 and not more than 1000 words in English.
- Written legibly in double space on the writing pad provided.
- The theme is announced on the day.

## Rules
- The essay must be original and not published before.
- Contestants bring their own materials.

## Judging
- Presentation and Style 40%.
- Form, Content and Insight 60%: Accuracy 20%, Fairness (balanced, sound) 20%, Methodology 20%.`},{Title:"Poster Making",Source:"Memorandum No. 79 s. 2017, Implementing Guidelines, On-the-Spot Skills Exhibition",Sections:{About:null,TimeAndFormat:null,Rules:["The theme is announced on the day.","Any artwork in the poster must be original in design.","Contestants bring their own materials: 1/4 illustration board and Craypas."],Allowed:null,NotAllowed:null,Judging:["Creativity and Presentation 50%.","Originality 30%.","Relevance to the Theme 20%."],Points:null,Notes:null},Markdown:`## Rules
- The theme is announced on the day.
- Any artwork in the poster must be original in design.
- Contestants bring their own materials: 1/4 illustration board and Craypas.

## Judging
- Creativity and Presentation 50%.
- Originality 30%.
- Relevance to the Theme 20%.`},{Title:"Jingle Writing and Singing",Source:"Memorandum No. 79 s. 2017, Implementing Guidelines, On-the-Spot Skills Exhibition",Sections:{About:null,TimeAndFormat:["The performance is done within two to three minutes.","The theme is announced on the day."],Rules:["The jingle is an original composition highlighting the theme.","The lyrics are in English.","Contestants bring their own materials."],Allowed:null,NotAllowed:null,Judging:["Lyrics (relevance to the theme) 50%.","Musicality (execution and overall performance) 30%.","Originality (creativity) 20%."],Points:null,Notes:null},Markdown:`## Time and format
- The performance is done within two to three minutes.
- The theme is announced on the day.

## Rules
- The jingle is an original composition highlighting the theme.
- The lyrics are in English.
- Contestants bring their own materials.

## Judging
- Lyrics (relevance to the theme) 50%.
- Musicality (execution and overall performance) 30%.
- Originality (creativity) 20%.`}],s=[],r=[{Key:"EventDate",Kind:"date",Label:"Festival date (2017 edition)",Value:"2017-09-19",Source:"Memorandum No. 79 s. 2017, item 1 (past edition)"},{Key:"EventTime",Kind:"text",Label:"Festival time (2017 edition)",Value:"8:00 A.M. to 5:00 P.M.",Source:"Memorandum No. 79 s. 2017, item 1"},{Key:"Venue",Kind:"address",Label:"Venue (2017 edition)",Value:{Name:"Gulod National High School",Address:"Gulod",City:"City of Cabuyao",MapUrl:"",Directions:""},Source:"Memorandum No. 79 s. 2017, item 1 (past edition)"},{Key:"RegistrationTime",Kind:"text",Label:"Registration time",Value:"30 minutes before the contest proper",Source:"Memorandum No. 79 s. 2017, item 4"},{Key:"Organiser",Kind:"contact",Label:"Division office and officials (2017)",Value:{Name:"Reynaldo A. Talavera, Ed. D (Division AP Coordinator)",Role:"Prepared the memorandum for the City Schools Division of Cabuyao; approved by the OIC Schools Division Superintendent",Phone:"",WhatsApp:"",Email:""},Source:"Memorandum No. 79 s. 2017, signatures; no phone or email printed"},{Key:"Announcements",Kind:"news",Label:"Notice in the memorandum",Value:[{Date:"2017-09-04",Title:"Festival of Talents (PopQuiz and On-the-Spot Skills Exhibition)",Text:"Memorandum No. 79 s. 2017 announced the Division PopQuiz and On-the-Spot Skills Exhibition on 19 September 2017 at Gulod National High School, Cabuyao.",Url:"https://depedcabuyao.ph/wp-content/uploads/2017/09/Festival-of-Talents-Popquiz-and-On-the-Spot-Skills-Exhibition.pdf"}],Source:"Memorandum No. 79 s. 2017, dated 4 September 2017"}],l=[{Claim:"Rules, eligibility and criteria for the 2017 Division Festival of Talents.",SourceType:"Primary - the event's own rules document",Source:"City Schools Division of Cabuyao, Division Memorandum No. 79 s. 2017",Url:"https://depedcabuyao.ph/wp-content/uploads/2017/09/Festival-of-Talents-Popquiz-and-On-the-Spot-Skills-Exhibition.pdf"}],u={TemplateKey:e,Year:2017,Note:n,Page:t,ParticipantTypes:i,AgeGroups:o,Competitions:a,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{o as AgeGroups,s as CompetitionAgeGroups,a as Competitions,l as Evidence,n as Note,t as Page,i as ParticipantTypes,e as TemplateKey,r as Variables,d as Year,u as default};
